/**
 * Golden vectors for the MMZ1 v1 zone table (UV-5R Mini MM9PDY target).
 *
 * Copied byte for byte from the firmware project's MMZ1 v1 contract (its `mmz1-v1.json`, generated by its
 * reference codec). Synthetic demo data only: no owner data. A change to the format is a new version (new
 * magic, new file), never an edit of these.
 *
 * `sectorHex` is the sector from 0xC000 up to the end of the last written byte (FF where nothing is written).
 * `frames` are the 64-byte clone W frames in write order. `slotIndexes` are 0-based (channel 1 = slot 0).
 */

export interface Mmz1VectorFrame {
  address: number;
  hex: string;
}

export interface Mmz1Vector {
  zones: { name: string; slotIndexes: number[] }[];
  sectorHex: string;
  crc: number;
  generation: number;
  frames: Mmz1VectorFrame[];
}

